using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;
namespace DesktopFish.Editor { public static class FishSmileReview {
const string Folder="work/ref-smile-rig-151";
public static void Review(){
 EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
 var root=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/DesktopFish/Rebuilt/BigFish.prefab"));
 var skins=root.GetComponentsInChildren<SkinnedMeshRenderer>();if(skins.Length!=2||skins.Any(s=>s.bones.Length!=58||s.sharedMesh.blendShapeCount!=6))throw new InvalidOperationException("151 shared58/6 expression rig absent");
 var motion=new FishMotion(root.transform){randomActions=false};motion.Tick(0,1,0,0,"idle",false);
 var snapshots=skins.Select(s=>{var o=new GameObject("151 actual preview");o.AddComponent<MeshFilter>().sharedMesh=new Mesh();o.AddComponent<MeshRenderer>().sharedMaterials=s.sharedMaterials;s.enabled=false;return o;}).ToArray();
 var camera=new GameObject("151 camera").AddComponent<Camera>();camera.orthographic=true;camera.allowHDR=false;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.clear;camera.nearClipPlane=.001f;camera.farClipPlane=10;camera.gameObject.AddComponent<FishPalette>().paletteShader=AssetDatabase.LoadAssetAtPath<Shader>("Assets/DesktopFish/Shaders/IllustratedPalette.shader");RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.78f,.81f,.9f);var light=new GameObject("Key").AddComponent<Light>();light.type=LightType.Directional;light.intensity=.9f;light.color=new Color(1,.97f,.94f);light.transform.rotation=Quaternion.Euler(35,-25,0);
 Action bake=()=>{for(int i=0;i<skins.Length;i++){var m=snapshots[i].GetComponent<MeshFilter>().sharedMesh;skins[i].BakeMesh(m);if(m.vertices.Any(p=>float.IsNaN(p.x)||float.IsNaN(p.y)||float.IsNaN(p.z)||float.IsInfinity(p.x)||float.IsInfinity(p.y)||float.IsInfinity(p.z)))throw new InvalidOperationException("151 invalid actual deformation");m.vertices=m.vertices.Select(skins[i].transform.TransformPoint).ToArray();m.normals=m.normals.Select(n=>skins[i].transform.localToWorldMatrix.inverse.transpose.MultiplyVector(n).normalized).ToArray();m.RecalculateBounds();}};
 Action<float,float,float,string> expressions=(joy,eye,blink,other)=>{foreach(var s in skins)for(int i=0;i<6;i++){string n=s.sharedMesh.GetBlendShapeName(i);s.SetBlendShapeWeight(i,n=="Fcl_ALL_Joy"?joy:n=="Fcl_EYE_Joy"?Mathf.Max(0,eye-joy):n=="Fcl_EYE_Close"?blink:n==other?100:0);}};
 foreach(float value in new[]{0f,65,90,100}){expressions(value,value,0,"");bake();foreach(int angle in new[]{0,35,90})Frame(camera,Folder+"/final-joy"+value+"-"+angle+".png",new Vector3(0,.735f,.10f),.16f,angle,900,600);Frame(camera,Folder+"/final-small"+value+".png",new Vector3(0,.56f,-.05f),.64f,0,180,240);}
 int combinations=0;for(int smile=0;smile<=100;smile+=5)for(int blink=0;blink<=100;blink+=10){expressions(smile,smile,blink*(1-smile*.01f),"");bake();combinations++;}
 int pose=0;foreach(var gesture in new[]{FishMotion.Gesture.None,FishMotion.Gesture.Cheer,FishMotion.Gesture.Wave,FishMotion.Gesture.Bow})foreach(float time in new[]{.3f,.65f,1f,2f,4.2f}){motion.Play(gesture,0);motion.Tick(time,1,pose%2==0?-1:1,pose%3==0?-1:1,gesture==FishMotion.Gesture.Cheer?"complete":pose%3==0?"working":"idle",false);expressions(motion.Joy,motion.SmileEyes,motion.BlinkWeight(),"");bake();Frame(camera,Folder+"/final-motion-"+pose+".png",new Vector3(0,.56f,-.05f),.64f,0,360,480);pose++;}
 motion.Play(FishMotion.Gesture.None,0);motion.Tick(0,1,0,0,"idle",false);foreach(string name in new[]{"Fcl_EYE_Close","Fcl_ALL_Fun","Fcl_ALL_Sorrow","Fcl_ALL_Surprised"}){expressions(0,0,name=="Fcl_EYE_Close"?100:0,name);bake();Frame(camera,Folder+"/final-other-"+name+".png",new Vector3(0,.735f,.10f),.16f,0,900,600);}
 File.WriteAllText(Folder+"/actual-expression-review.json","{\"joints\":58,\"shared_meshes\":2,\"shared_expression_names\":6,\"finite_smile_blink_combinations\":"+combinations+",\"affected_head_neck_shoulder_gesture_samples\":"+pose+",\"default_head_views\":12,\"full_collision_claim\":false}");Debug.Log("151 actual shared expression and affected rig review passed");
}
static void Frame(Camera c,string path,Vector3 focus,float size,int angle,int w,int h){c.aspect=w/(float)h;c.orthographicSize=size;c.transform.position=focus+Quaternion.Euler(0,angle,0)*new Vector3(0,.10f,3);c.transform.LookAt(focus);var rt=RenderTexture.GetTemporary(w,h,24);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var im=new Texture2D(w,h,TextureFormat.RGBA32,false);im.ReadPixels(new Rect(0,0,w,h),0,0);im.Apply();File.WriteAllBytes(path,im.EncodeToPNG());c.targetTexture=null;RenderTexture.active=null;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(im);}
}}
